 return S.gifts.filter(g=>g.storeId===storeId&&g.active&&g.stock>0&&(sub==null||sub>=g.min)&&(g.scope==="all"||!pids||pids.includes(g.scope))).sort((a,b)=>b.min-a.min)[0]||null;
