/* ================= cart & checkout ================= */
function cartGroups(){
 const g={};
 S.cart=S.cart.filter(c=>getProd(c.pid));
 S.cart.forEach((c,idx)=>{const p=getProd(c.pid);(g[p.storeId]=g[p.storeId]||[]).push({...c,idx,p,unit:priceOf(p,c.vi??-1).now})});
 return Object.entries(g).map(([sid,items])=>{
  const sub=items.reduce((a,x)=>a+x.unit*x.qty,0);
  const st=getStore(sid); const s=S.settings.ship;
  let opts=["dhaka","outside","pickup","negotiated"].filter(k=>s[k].on&&items.every(x=>x.p.ship[k])&&(k!=="pickup"||st.pickup)); if(!opts.length) opts=["negotiated"];
  const sel=opts.includes(UI.ship[sid])?UI.ship[sid]:opts[0]; UI.ship[sid]=sel;
  const fee=sel==="negotiated"||sel==="pickup"?0:s[sel].fee;
  let disc=0,cErr=""; const code=UI.coupons[sid];
  if(code){const c=S.coupons.find(x=>x.storeId===sid&&x.code.toUpperCase()===code.toUpperCase()&&x.active&&x.expires>=today()&&x.used<x.limit);
   if(!c) cErr=t("coupon_bad"); else if(sub<c.min) cErr=t("coupon_min",{m:money(c.min)}); else disc=c.type==="pct"?Math.round(sub*c.value/100):Math.min(c.value,sub);}
  const gift=giftFor(sid,sub,items.map(x=>x.p.id));
  return {sid,st,items,sub,opts,sel,fee,disc,cErr,code,gift,total:sub-disc+fee};
 });
}
